export function getPokemonId(name: string): number {
  const kantoIdx = pokedexOrder.indexOf(name);
  if (kantoIdx !== -1) return kantoIdx + 1;
  const johtoIdx = pokedexOrderJohto.indexOf(name);
  if (johtoIdx !== -1) return johtoIdx + 152;
  const hoennIdx = pokedexOrderHoenn.indexOf(name);
  if (hoennIdx !== -1) return hoennIdx + 252;
    const sinnohIdx = pokedexOrderSinnoh.indexOf(name);
    if (sinnohIdx !== -1) return sinnohIdx + 387;
      const teseliaIdx = pokedexOrderTeselia.indexOf(name);
      if (teseliaIdx !== -1) return teseliaIdx + 494;
     const kalosIdx = pokedexOrderKalos.indexOf(name);
     if (kalosIdx !== -1) return kalosIdx + 650;
     const alolaIdx = pokedexOrderAlola.indexOf(name);
      if (alolaIdx !== -1) return alolaIdx + 722;
     const galarIdx = pokedexOrderGalar.indexOf(name);
       if (galarIdx !== -1) return galarIdx + 810;
    const paldeaIdx = pokedexOrderPaldea.indexOf(name);
     if (paldeaIdx !== -1) return paldeaIdx + 906;
  const todosIdx = pokedexOrderTodos.indexOf(name);
   if (todosIdx !== -1) return todosIdx + 1;
  return 0;
}

export function getPokemonSprite(name: string): string {
  const id = getPokemonId(name);
  if (id === 0) return "";
  return `https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/${id}.png`;
}
